import z3

n = 7
# P[i][j][k] true if x[i][j] == k
P = [[[z3.Bool(f'p_{i}_{j}_{k}') for k in range(n)] for j in range(n)] for i in range(n)]

s = z3.Solver()

# Exactly one value per cell
for i in range(n):
    for j in range(n):
        s.add(z3.ExactlyOne([P[i][j][k] for k in range(n)]))

# Idempotent: x[i][i] == i => P[i][i][i]
for i in range(n):
    s.add(P[i][i][i])

# Latin square: each row, each symbol once; each col, each symbol once
for i in range(n):
    for k in range(n):
        # row i has k exactly once
        s.add(z3.ExactlyOne([P[i][j][k] for j in range(n)]))
        # col i has k exactly once
        s.add(z3.ExactlyOne([P[j][i][k] for j in range(n)]))

# QG3: x[ x[i][j] ][ x[j][i] ] == i
# For all i,j, for all a,b: if x[i][j]==a and x[j][i]==b then x[a][b]==i
for i in range(n):
    for j in range(n):
        for a in range(n):
            for b in range(n):
                s.add(z3.Implies(z3.And(P[i][j][a], P[j][i][b]), P[a][b][i]))

# Check
result = s.check()
print(result)

if result == z3.sat:
    m = s.model()
    grid = [[-1]*n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            for k in range(n):
                if m.evaluate(P[i][j][k]):
                    grid[i][j] = k
                    break
    flat = [grid[i][j] for i in range(n) for j in range(n)]
    print(flat)
    # Also print the grid nicely
    for row in grid:
        print(row)
else:
    print("UNSATISFIABLE")

