import z3

def check_qg3(n):
    P = [[[z3.Bool(f'p_{i}_{j}_{k}') for k in range(n)] for j in range(n)] for i in range(n)]
    s = z3.Solver()
    for i in range(n):
        for j in range(n):
            s.add(z3.Sum([z3.If(P[i][j][k], 1, 0) for k in range(n)]) == 1)
    for i in range(n):
        s.add(P[i][i][i])
    for i in range(n):
        for k in range(n):
            s.add(z3.Sum([z3.If(P[i][j][k], 1, 0) for j in range(n)]) == 1)
            s.add(z3.Sum([z3.If(P[j][i][k], 1, 0) for j in range(n)]) == 1)
    for i in range(n):
        for j in range(n):
            for a in range(n):
                for b in range(n):
                    s.add(z3.Implies(z3.And(P[i][j][a], P[j][i][b]), P[a][b][i]))
    result = s.check()
    return str(result)

